CREATE TABLE "comments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE, "recording_id" uuid NOT NULL REFERENCES "recordings"("id") ON DELETE CASCADE, "author_user_id" uuid REFERENCES "users"("id") ON DELETE SET NULL, "guest_name" text, "guest_key_hash" text, "body" text NOT NULL, "timestamp_ms" integer NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, "deleted_at" timestamptz, CONSTRAINT "comments_author_check" CHECK (("author_user_id" IS NOT NULL) OR ("guest_name" IS NOT NULL AND "guest_key_hash" IS NOT NULL)));
CREATE INDEX "comments_recording_created_idx" ON "comments" ("recording_id", "created_at");
CREATE TABLE "comment_reactions" ("comment_id" uuid NOT NULL REFERENCES "comments"("id") ON DELETE CASCADE, "actor_key_hash" text NOT NULL, "emoji" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, PRIMARY KEY ("comment_id", "actor_key_hash", "emoji"));
CREATE INDEX "comment_reactions_comment_idx" ON "comment_reactions" ("comment_id");
